import React from 'react';
// Pastikan path (jalur) import disesuaikan dengan tempat Anda menyimpan file.
// Jika file berada di dalam folder 'components', gunakan './components/RegistrationForm'
import RegistrationForm from './components/RegistrationForm'; 
import LoginForm from './components/LoginForm';

function App() {
  return (
    // Style dasar untuk memberikan jarak dan warna latar belakang pada halaman
    <div style={{ backgroundColor: '#f4f7f6', minHeight: '100vh', padding: '2rem 0' }}>

      {/* Menampilkan komponen Form Registrasi */}
      <RegistrationForm />

      {/* Garis pemisah antara form registrasi dan form login */}
      <hr style={{ maxWidth: '500px', margin: '3rem auto', borderTop: '2px solid #e0e0e0' }} />

      {/* Menampilkan komponen Form Login (Hasil dan Pembahasan) */}
      <LoginForm />

    </div>
  );
}

export default App;
